export function isEqualRenderable(a, b) {
    if (a === b)
        return true;
    if (!a || !b)
        return false;
    if (a instanceof Date && b instanceof Date) {
        return a.getTime() === b.getTime();
    }
    if (a instanceof Uint8Array && b instanceof Uint8Array) {
        return a.length === b.length && a.every((x, i) => x === b[i]);
    }
    if (Array.isArray(a) && Array.isArray(b)) {
        return a.length === b.length && a.every((x, i) => x === b[i]);
    }
    return false;
}
export function renderableToQueryParam(v) {
    if (v == null)
        return "";
    switch (typeof v) {
        case "string":
            return v;
        case "number":
            return v.toString();
        case "boolean":
            return v ? "1" : "0";
        case "object":
            if (v instanceof Date) {
                return v.toISOString();
            }
    }
    return "";
}
